//
//      high speed sfr address define
//
//===============================================================================//
//............. 0x0200 - 0x02ff............
typedef struct {
    ___RW ___u32(CON);
#define JL_INTEST_BASE                  (lsfr_base + map_adr(0x02, 0x00))
#define JL_INTEST                       ((JL_INTEST_TypeDef     *)JL_INTEST_BASE)

//............. 0x0300 - 0x03ff............

//............. 0x0400 - 0x07ff............
